var t=[{title:`Proč k ní dochází`,text:`DOMS obvykle následuje po neznámých pohybech a opakovaných excentrických kontrakcích, kdy sval vyvíjí sílu, zatímco se prodlužuje. Podílí se několik procesů ve svalu a okolní tkáni. Příčinou není zbytková kyselina mléčná. To, jak moc vás svaly bolí, neměří, jak dobrý trénink byl.`},{title:`Jak přichází a odchází`,text:`Bolest může začít několik hodin po tréninku, v následujících jednom až třech dnech zesílit a pak odeznít. Známý cvik často způsobuje při stejné dávce menší bolest, čemuž se říká efekt opakovaného zatížení. K budování síly nepotřebujete silnou ani dlouhotrvající bolest svalů.`},{title:`Trénink s bolestí svalů`,text:`Mírná, rozlitá svalová bolest obvykle stále dovoluje chůzi, mobilitu nebo lehčí trénink, pokud se dobře pohybujete. Pokud bolest omezuje běžný pohyb nebo mění techniku zvedání, snižte intenzitu nebo si dejte víc regenerace. Okamžité opakování neznámého tréninku s vysokým objemem je zřídka dobrý způsob, jak postupovat. Známé cviky ztěžujte postupně a nespoléhejte na to, že protahování nebo zklidnění zabrání bolesti následující den.`},{title:`Kdy vyhledat pomoc`,text:`Ostrá bolest na jednom místě, výrazný otok, zřetelná slabost, tmavá moč, horečka nebo příznaky, které se zhoršují místo aby ustupovaly, nejsou normální DOMS. Závažné příznaky, zejména tmavá moč se svalovou bolestí nebo slabostí, vyžadují rychlé lékařské vyšetření.`},{title:`Použití v TrainUp`,text:`Po tréninku můžete nahlásit bolest nebo nepohodlí s částí těla a cvikem. Jakákoli nedávná bolest znamená, že plán při opětovném vytvoření nebude těžší. Pokud cvik během tréninku bolí, klepněte na „Cítím bolest“, aby se okamžitě ukončil; zůstane mimo vaše plány, dokud ho nevrátíte v Profilu.`}];var n=[{label:`NHS: opožděná bolest svalů`,url:`https://www.leicspart.nhs.uk/msk-physiotherapy-resources-getting-started/msk-physiotherapy-resources-faqs/`},{label:`Přehledová studie: opožděná bolest svalů`,url:`https://pmc.ncbi.nlm.nih.gov/articles/PMC13627368/`},{label:`Stanovisko ACSM z roku 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var s={sections:t,sources:n};export{s as default,t as sections,n as sources};